CREATE TABLE training_plan (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 member_id BIGINT NOT NULL REFERENCES member(id), coach_id BIGINT NOT NULL REFERENCES sys_user(id), venue_id BIGINT NOT NULL REFERENCES venue(id),
 title VARCHAR(100) NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 100),
 goal VARCHAR(20) NOT NULL CHECK (goal IN ('FAT_LOSS','MUSCLE_GAIN','POSTURE','ENDURANCE','GENERAL')),
 start_date DATE NOT NULL, end_date DATE NOT NULL, note VARCHAR(1000),
 status VARCHAR(20) NOT NULL CHECK (status IN ('DRAFT','ACTIVE','ARCHIVED')),
 version BIGINT NOT NULL DEFAULT 0 CHECK (version>=0), active_member_key VARCHAR(80) UNIQUE,
 created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL,
 CHECK (end_date>=start_date AND end_date<=start_date + 365),
 CHECK ((status='ACTIVE' AND active_member_key IS NOT NULL AND active_member_key=cast(venue_id AS VARCHAR) || '/' || cast(member_id AS VARCHAR)) OR (status<>'ACTIVE' AND active_member_key IS NULL))
);
CREATE TABLE training_plan_exercise (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, plan_id BIGINT NOT NULL REFERENCES training_plan(id),
 position INTEGER NOT NULL CHECK (position BETWEEN 1 AND 20), name VARCHAR(100) NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100),
 mode VARCHAR(20) NOT NULL CHECK(mode IN ('STRENGTH','DURATION')),
 sets INTEGER, reps INTEGER, weight_kg NUMERIC(7,2), minutes INTEGER, note VARCHAR(300), UNIQUE(plan_id,position),
 CHECK ((mode='STRENGTH' AND sets IS NOT NULL AND sets BETWEEN 1 AND 20 AND reps IS NOT NULL AND reps BETWEEN 1 AND 200 AND (weight_kg IS NULL OR weight_kg BETWEEN 0 AND 500) AND minutes IS NULL) OR (mode='DURATION' AND minutes IS NOT NULL AND minutes BETWEEN 1 AND 240 AND sets IS NULL AND reps IS NULL AND weight_kg IS NULL))
);
CREATE TABLE training_session (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, plan_id BIGINT NOT NULL REFERENCES training_plan(id), version BIGINT NOT NULL DEFAULT 0 CHECK(version>=0),
 performed_on DATE NOT NULL, duration_minutes INTEGER NOT NULL CHECK(duration_minutes BETWEEN 1 AND 240), effort INTEGER CHECK(effort BETWEEN 1 AND 10), note VARCHAR(1000),
 booking_id BIGINT REFERENCES booking(id), active_booking_key BIGINT UNIQUE REFERENCES booking(id), course_name VARCHAR(100),
 status VARCHAR(20) NOT NULL CHECK(status IN ('COMPLETED','VOIDED')), void_reason VARCHAR(300), coach_name VARCHAR(50) NOT NULL, created_at TIMESTAMP NOT NULL,
 feedback_rating INTEGER CHECK(feedback_rating BETWEEN 1 AND 5), feedback_content VARCHAR(500), feedback_at TIMESTAMP,
 CHECK ((status='COMPLETED' AND void_reason IS NULL AND ((active_booking_key IS NOT NULL AND booking_id IS NOT NULL AND active_booking_key=booking_id) OR (active_booking_key IS NULL AND booking_id IS NULL))) OR (status='VOIDED' AND active_booking_key IS NULL AND void_reason IS NOT NULL AND length(trim(void_reason)) BETWEEN 1 AND 300))
);
CREATE TABLE training_session_exercise (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, session_id BIGINT NOT NULL REFERENCES training_session(id), exercise_id BIGINT NOT NULL REFERENCES training_plan_exercise(id),
 position INTEGER NOT NULL CHECK(position BETWEEN 1 AND 20), name VARCHAR(100) NOT NULL, mode VARCHAR(20) NOT NULL CHECK(mode IN ('STRENGTH','DURATION')),
 sets INTEGER, reps INTEGER, weight_kg NUMERIC(7,2), minutes INTEGER, status VARCHAR(20) NOT NULL CHECK(status IN ('DONE','SKIPPED')), note VARCHAR(300),
 target_sets INTEGER, target_reps INTEGER, target_weight_kg NUMERIC(7,2), target_minutes INTEGER, UNIQUE(session_id,exercise_id),
 CHECK ((status='SKIPPED' AND note IS NOT NULL AND length(trim(note)) BETWEEN 1 AND 300 AND sets IS NULL AND reps IS NULL AND weight_kg IS NULL AND minutes IS NULL) OR (status='DONE' AND ((mode='STRENGTH' AND sets IS NOT NULL AND sets BETWEEN 1 AND 20 AND reps IS NOT NULL AND reps BETWEEN 1 AND 200 AND (weight_kg IS NULL OR weight_kg BETWEEN 0 AND 500) AND minutes IS NULL) OR (mode='DURATION' AND minutes IS NOT NULL AND minutes BETWEEN 1 AND 240 AND sets IS NULL AND reps IS NULL AND weight_kg IS NULL)))),
 CHECK ((mode='STRENGTH' AND target_sets IS NOT NULL AND target_sets BETWEEN 1 AND 20 AND target_reps IS NOT NULL AND target_reps BETWEEN 1 AND 200 AND (target_weight_kg IS NULL OR target_weight_kg BETWEEN 0 AND 500) AND target_minutes IS NULL) OR (mode='DURATION' AND target_minutes IS NOT NULL AND target_minutes BETWEEN 1 AND 240 AND target_sets IS NULL AND target_reps IS NULL AND target_weight_kg IS NULL))
);
CREATE TABLE training_plan_event (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, member_id BIGINT NOT NULL REFERENCES member(id), actor_id BIGINT NOT NULL REFERENCES sys_user(id), plan_id BIGINT NOT NULL REFERENCES training_plan(id), session_id BIGINT REFERENCES training_session(id),
 type VARCHAR(30) NOT NULL CHECK(type IN ('CREATE','DRAFT','PUBLISH','ARCHIVE','RECORD','VOID','FEEDBACK')), actor_name VARCHAR(50) NOT NULL, created_at TIMESTAMP NOT NULL, reason VARCHAR(1000),
 idempotency_key VARCHAR(80) NOT NULL CHECK(length(idempotency_key) BETWEEN 8 AND 80), request_digest VARCHAR(64) NOT NULL CHECK(length(request_digest)=64), UNIQUE(member_id,actor_id,idempotency_key)
);
CREATE INDEX idx_training_plan_scope ON training_plan(venue_id,coach_id,status,id);
CREATE INDEX idx_training_plan_member ON training_plan(member_id,status,id);
CREATE INDEX idx_training_session_history ON training_session(plan_id,performed_on,id);
CREATE INDEX idx_training_session_completed ON training_session(plan_id,status,performed_on);
CREATE INDEX idx_training_plan_event_history ON training_plan_event(plan_id,id);
CREATE INDEX idx_training_session_exercise_session ON training_session_exercise(session_id,position);
